-- =============================================================================
-- NaKmetiji.si — Znamenitosti (POI) + Green Passport tables
-- Migration: 20260412_znamenitosti_green_stamps
-- =============================================================================

-- ── 1. Znamenitosti — Points of Interest ──────────────────────────────────────
-- Used by the Oracle AI concierge for geo-enrichment:
-- "3 km from the farm you'll find Slap Savica..."

CREATE TABLE IF NOT EXISTS public.znamenitosti (
  id          UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  ime         TEXT        NOT NULL,
  opis        TEXT,
  zanimivost  TEXT,                     -- interesting fact / "did you know"
  kategorija  TEXT        NOT NULL CHECK (kategorija IN ('slap','gora','pot','muzej','jezero','jama')),
  lat         DOUBLE PRECISION NOT NULL,
  lng         DOUBLE PRECISION NOT NULL,
  slika_url   TEXT,
  regija      TEXT        NOT NULL
);

-- Index for bounding-box pre-filter (faster than full Haversine scan)
CREATE INDEX IF NOT EXISTS idx_znamenitosti_regija ON znamenitosti (regija);
CREATE INDEX IF NOT EXISTS idx_znamenitosti_lat_lng ON znamenitosti (lat, lng);

-- Anyone can read landmarks (they're public POIs)
ALTER TABLE public.znamenitosti ENABLE ROW LEVEL SECURITY;
CREATE POLICY "znamenitosti_javno" ON public.znamenitosti FOR SELECT USING (true);
CREATE POLICY "znamenitosti_admin" ON public.znamenitosti FOR ALL USING (
  EXISTS (SELECT 1 FROM public.profili WHERE id = auth.uid() AND vloga = 'super_admin')
);

-- ── 2. Seed: ~190 verified Slovenian landmarks ────────────────────────────────
ON CONFLICT DO NOTHING;

-- ── 3. Green Stamps — guests collect stamps for eco stays ────────────────────

CREATE TABLE IF NOT EXISTS public.green_badges (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  ime         TEXT NOT NULL,
  opis        TEXT,
  ikona       TEXT,
  stopnja     INTEGER DEFAULT 1,
  ustvarjeno  TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.kmetija_green_badges (
  kmetija_id  UUID REFERENCES public.kmetije(id) ON DELETE CASCADE,
  badge_id    UUID REFERENCES public.green_badges(id) ON DELETE CASCADE,
  dodeljeno   TIMESTAMPTZ DEFAULT NOW(),
  PRIMARY KEY (kmetija_id, badge_id)
);

CREATE TABLE IF NOT EXISTS public.green_stamps (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  gost_id         UUID NOT NULL REFERENCES public.profili(id) ON DELETE CASCADE,
  kmetija_id      UUID NOT NULL REFERENCES public.kmetije(id) ON DELETE CASCADE,
  rezervacija_id  UUID REFERENCES public.rezervacije(id) ON DELETE SET NULL,
  ustvarjeno      TIMESTAMPTZ DEFAULT NOW(),
  skenirano       BOOLEAN DEFAULT TRUE
);

-- One stamp per guest per farm (unique index — reservation link prevents abuse)
CREATE UNIQUE INDEX IF NOT EXISTS green_stamps_unique
  ON public.green_stamps (gost_id, kmetija_id);

ALTER TABLE public.green_badges       ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.kmetija_green_badges ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.green_stamps       ENABLE ROW LEVEL SECURITY;

-- Badges: public read
CREATE POLICY "green_badges_javno"         ON public.green_badges         FOR SELECT USING (true);
CREATE POLICY "kmetija_green_badges_javno" ON public.kmetija_green_badges FOR SELECT USING (true);

-- Stamps: each guest sees only their own
CREATE POLICY "green_stamps_gost"   ON public.green_stamps FOR SELECT USING (gost_id = auth.uid());
CREATE POLICY "green_stamps_insert" ON public.green_stamps FOR INSERT WITH CHECK (gost_id = auth.uid());

-- Admin full access
CREATE POLICY "green_badges_admin"    ON public.green_badges    FOR ALL USING (
  EXISTS (SELECT 1 FROM public.profili WHERE id = auth.uid() AND vloga = 'super_admin')
);
CREATE POLICY "green_stamps_admin"    ON public.green_stamps    FOR ALL USING (
  EXISTS (SELECT 1 FROM public.profili WHERE id = auth.uid() AND vloga = 'super_admin')
);

-- Service role can insert stamps on confirmed booking
GRANT INSERT ON public.green_stamps TO service_role;
